# Class B kits of the C cars (doc 65: "keep a favourite viable"): the same body with flares, Tuner wheels and aero.
import copy as _copy
def _kit(base,name,blurb,wheel,fenders,extras,drop=(),chop=0,**over):
    r=_copy.deepcopy(RECIPES[base]);r.update(name=name,blurb=blurb,fenders=fenders,**over)
    if chop:   # a chopped roof: the roof (and so the screen's top) comes down
        r['glass']=dict(r['glass'],roof=r['glass']['roof']-chop)
        if 'cabin' in r:r['cabin']=dict(r['cabin'],roofline=[(y,z-chop if z>r['glass']['roof']-.4 else z) for y,z in r['cabin']['roofline']])
    r['wheel']=dict(r['wheel'],**wheel)
    r['extras']=[e for e in r['extras'] if e not in drop]+[e for e in extras if e not in r['extras']];return r
RECIPES['sprint_tuner']=_kit('sprint','Sprint Tuner','Hot hatch, tuned',dict(style='six',finish='white',tyre='road',width=1.05,dish=.02),
                             dict(front=(.04,.28,.50),rear=(.04,.28,.50)),['scoop'])
RECIPES['comet_tuner']=_kit('comet','Comet Tuner','Rear-drive coupe, tuned',dict(style='split',finish='bronze',tyre='road',width=1.06,dish=.04),
                            dict(front=(.05,.30,.55),rear=(.07,.32,.62)),['wing','skirts'])
