# Kit experiments (Richard, 6 Oct: the bolt-on arches looked bolted on and floating; try spoilers, bonnet air parts, a
# go-faster stripe, a sportier body, a lowered screen). Four cars try different treatments first; the rest keep their
# wheels and modest flares until the treatments are chosen.
_EXPERIMENTS={
 # Quarry Hills' off-roaders (Richard, 7 Oct: "sort the Tier B for the mining town"): lifted, not lowered (negative
 # `lower`), bigger knobblies, and each a first step a later tier can grow (Dakar, Baja, trophy truck).
 'cob':    dict(extras=['race_stripes','bonnet_vents','skid_plate','roundel','light_bar'],lower=-.05,race_number=4,wheel=dict(r=.49)),
 'drover': dict(extras=['race_stripes','skid_plate','roundel'],drop=['bull_bar'],lower=-.07,race_number=11,wheel=dict(r=.50,track=.90),
                stripe_colour=(.92,.92,.88)),
 'scamp':  dict(extras=['race_stripes','roof_scoop','bonnet_vents','spots','roundel','spoiler'],drop=['roof_rails','stripe','light_bar'],race_number=27,
                stripe_colour=(.04,.045,.05)),
 'fell':   dict(extras=['roof_tyres','light_bar','skid_plate','roundel'],drop=['spots'],lower=-.05,race_number=8,wheel=dict(r=.48)),
 'tumbler':dict(extras=['light_bar','skid_plate','race_stripes'],drop=['spots'],lower=-.09,wheel=dict(r=.52,track=.88)),
 'hauler': dict(extras=['roof_wing','side_exhaust','canards','race_stripes'],drop=['light_bar','scoop'],
                stripe_colour=(.92,.92,.88)),
 # The big box cars (Richard: be brave; picture them one day in class S, lapping the Nurburgring, so each B part is a
 # first step that later tiers can grow: the roof wing gets bigger, the stance lower, the body wider).
 'picnic': dict(extras=['race_stripes','roof_wing','bonnet_vents','splitter','skirts'],drop=['rubbing_strip','roof_rails','sunroof'],lower=.06),
 'kipper': dict(extras=['race_stripes','roof_wing','canards','side_exhaust','splitter','skirts'],drop=['ladder','mudflaps'],lower=.06,
                stripe_colour=(.92,.92,.88)),
 'puddle': dict(extras=['race_stripes','bonnet_vents','spoiler','splitter'],lower=.06),
 'marlow': dict(extras=['scoop','ducktail','splitter','skirts'],lower=.06,chop=.10),
 'bramble':dict(extras=['race_stripes','wing','bonnet_vents','skirts'],drop=['scoop'],lower=.06,stripe_colour=(.04,.045,.05)),
 'beetle': dict(extras=['ducktail'],lower=.07,chop=.07),
}
for _b,(_blurb,_w,(_ff,_fr),_add,_drop,_over) in _KITS.items():
    _over=dict(_over);_x=_EXPERIMENTS.get(_b,{});_add=[e for e in list(_add)+[e for e in _x.get('extras',[]) if e not in _add] if e not in _x.get('drop',[])]
    _drop=list(_drop)+list(_x.get('drop',[]));_over.update({k:v for k,v in _x.items() if k not in ('extras','drop','wheel')})
    if 'wheel' in _x:_w=dict(_w,**_x['wheel'])
    RECIPES[_b+'_tuner']=_kit(_b,RECIPES[_b]['name']+' Tuner',_blurb,_w,dict(front=_ff,rear=_fr),_add,_drop,**_over)
KIT_ORDER=[k+'_tuner' for k in ORDER if k+'_tuner' in RECIPES]
